using System;
using UnityEngine;

[AddComponentMenu("Chaos/Components/Movement")]
public class Movement : ComponentBase
{
	public SyncedNumVarStat moveSpeedStat;

	public SyncedNumVarStat dashSpeedStat;

	public SyncedNumVarStat dashDurationStat;

	public Vector2 moveVector;

	public Vector2 dashVector;

	public float dashTimer;

	private bool dashInitiated;

	public float snapDistance = 0.12f;

	public bool moveTowards;

	public bool snapTo;

	[HideInInspector]
	public float orbitAngle;

	private bool orbitClockwise;

	public Vector2 orbitVector;

	public bool orbit;

	public float orbitSpeed = 0.1f;

	public float orbitRadius = 3f;

	private Vector2 preventVector;

	[HideInInspector]
	public bool preventUpMovement;

	[HideInInspector]
	public bool preventDownMovement;

	[HideInInspector]
	public bool preventLeftMovement;

	[HideInInspector]
	public bool preventRightMovement;

	private float calcDistance;

	private const float circlePi = (float)Math.PI * 2f;

	public void Awake()
	{
		dashTimer = dashDurationStat.CurrentValue;
	}

	public void RemoveAllPrevents(bool xAxis = true, bool yAxis = true)
	{
		if (yAxis)
		{
			preventUpMovement = false;
			preventDownMovement = false;
		}
		if (xAxis)
		{
			preventLeftMovement = false;
			preventRightMovement = false;
		}
	}

	private void PreventMovementInDirection()
	{
		if (preventUpMovement)
		{
			ZeroMovementOnAxis(xAxis: false, negative: false);
		}
		if (preventDownMovement)
		{
			ZeroMovementOnAxis(xAxis: false, negative: true);
		}
		if (preventLeftMovement)
		{
			ZeroMovementOnAxis(xAxis: true, negative: true);
		}
		if (preventRightMovement)
		{
			ZeroMovementOnAxis(xAxis: true, negative: false);
		}
	}

	private void UpdateZeroedVelocity(Vector2 moveVec)
	{
		preventVector = rigidbody2D.velocity;
		if (moveVec.x == 0f)
		{
			preventVector.x = 0f;
		}
		if (moveVec.y == 0f)
		{
			preventVector.y = 0f;
		}
		rigidbody2D.velocity = preventVector;
	}

	private void ZeroMovementOnAxis(bool xAxis, bool negative)
	{
		if (xAxis)
		{
			if (negative)
			{
				if (moveVector.x < 0f)
				{
					moveVector.x = 0f;
				}
				if (dashVector.x < 0f)
				{
					dashVector.x = 0f;
				}
			}
			else
			{
				if (moveVector.x > 0f)
				{
					moveVector.x = 0f;
				}
				if (dashVector.x > 0f)
				{
					dashVector.x = 0f;
				}
			}
		}
		else if (negative)
		{
			if (moveVector.y < 0f)
			{
				moveVector.y = 0f;
			}
			if (dashVector.y < 0f)
			{
				dashVector.y = 0f;
			}
		}
		else
		{
			if (moveVector.y > 0f)
			{
				moveVector.y = 0f;
			}
			if (dashVector.y > 0f)
			{
				dashVector.y = 0f;
			}
		}
	}

	public void MoveOnInput(ChaosInputDevice inputDev, bool useAddForce = false)
	{
		moveVector = inputDev.GetMoveVector();
		if (!(moveVector == Vector2.zero))
		{
			PreventMovementInDirection();
			bool useAddForce2 = useAddForce;
			MoveToMoveVector(0f, useAddForce2);
		}
	}

	public void MoveToMoveVector(float speed = 0f, bool useAddForce = false)
	{
		if (speed == 0f)
		{
			speed = moveSpeedStat.CurrentValue;
		}
		if (useAddForce)
		{
			rigidbody2D.AddRelativeForce(moveVector * speed, ForceMode2D.Impulse);
		}
		else
		{
			rigidbody2D.velocity = moveVector * speed;
		}
		UpdateZeroedVelocity(moveVector);
	}

	public bool MoveToTarget(Transform otherTrans, float boundRadius = 0f, float speed = 0f)
	{
		return otherTrans == null || MoveToTarget(otherTrans.position, boundRadius, speed);
	}

	public bool MoveToTarget(Vector2 target, float boundRadius = 0f, float speed = 0f, bool dryRun = false, bool endMovementOnFinish = true)
	{
		if (speed == 0f)
		{
			speed = moveSpeedStat.CurrentValue;
		}
		if (boundRadius < 0f)
		{
			moveTowards = false;
			boundRadius *= -1f;
		}
		else
		{
			moveTowards = true;
			snapTo = boundRadius == 0f;
		}
		moveVector = (target - (Vector2)transform.position).normalized;
		calcDistance = Vector2.Distance(target, transform.position);
		bool flag;
		if (moveTowards)
		{
			flag = ((!snapTo) ? (calcDistance < boundRadius) : (calcDistance < snapDistance));
		}
		else
		{
			flag = calcDistance > boundRadius;
		}
		if (dryRun)
		{
			return flag;
		}
		if (flag)
		{
			if (snapTo)
			{
				transform.position = target;
			}
			if (endMovementOnFinish)
			{
				EndMovement();
			}
		}
		else
		{
			rigidbody2D.velocity = moveVector * speed;
			UpdateZeroedVelocity(moveVector);
		}
		return flag;
	}

	public bool DashToTarget(Vector2? target = null, bool snap = false, bool ignoreDashTimer = false, bool endMovementOnFinish = true)
	{
		snapTo = snap;
		if (target.HasValue)
		{
			dashVector = (target.Value - (Vector2)transform.position).normalized;
		}
		if (snapTo)
		{
			if (Vector2.Distance(target.Value, transform.position) < snapDistance)
			{
				transform.position = target.Value;
				dashInitiated = false;
				if (endMovementOnFinish)
				{
					EndMovement();
				}
				return true;
			}
			PreventMovementInDirection();
			rigidbody2D.velocity = dashVector * dashSpeedStat.CurrentValue;
			return false;
		}
		if (!dashInitiated)
		{
			dashInitiated = true;
			dashTimer = dashDurationStat.CurrentValue;
		}
		else if (!ignoreDashTimer)
		{
			dashTimer -= Time.fixedDeltaTime;
		}
		if (dashTimer > 0f)
		{
			PreventMovementInDirection();
			rigidbody2D.velocity = dashVector * dashSpeedStat.CurrentValue;
			return false;
		}
		dashInitiated = false;
		if (endMovementOnFinish)
		{
			EndMovement();
		}
		return true;
	}

	public void InitOrbitAngle(float givenAngle, bool clockwise = true)
	{
		orbitClockwise = clockwise;
		orbitAngle = givenAngle;
		orbitVector.x = Mathf.Cos(orbitAngle);
		orbitVector.y = Mathf.Sin(0f - orbitAngle);
		if (orbitAngle < 0f || orbitAngle > (float)Math.PI * 2f)
		{
			orbitAngle = Globals.TrueMod(orbitAngle, (float)Math.PI * 2f);
		}
	}

	public void InitOrbitAngle(Vector2 normalVec, bool clockwise = true)
	{
		float num = Vector2.Angle(Vector2.up, normalVec);
		num = ((!(normalVec.x < 0f)) ? (num - 90f) : (270f - num)) * ((float)Math.PI / 180f);
		InitOrbitAngle(num, clockwise);
	}

	public void OrbitTarget(Vector2 target, bool useTransform = false)
	{
		orbitVector *= orbitRadius;
		orbitVector += target;
		if (useTransform)
		{
			transform.position = orbitVector;
		}
		else
		{
			rigidbody2D.velocity = (orbitVector - (Vector2)transform.position) * moveSpeedStat.CurrentValue;
		}
		if (orbit)
		{
			orbitAngle += orbitSpeed * Time.deltaTime * (float)(orbitClockwise ? 1 : (-1));
			if (orbitAngle >= (float)Math.PI * 2f)
			{
				orbitAngle -= (float)Math.PI * 2f;
			}
		}
		orbitVector.x = Mathf.Cos(orbitAngle);
		orbitVector.y = Mathf.Sin(0f - orbitAngle);
	}

	public void EndMovement()
	{
		dashInitiated = false;
		if (rigidbody2D != null)
		{
			rigidbody2D.velocity = Vector2.zero;
		}
	}
}
