	private static float CurrentTimeScale
	{
		get
		{
			return Time.timeScale;
		}
		set
		{
			Time.timeScale = value;
			Time.fixedDeltaTime = value * 0.01f;
		}
	}

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
			originalTimeScale = Time.timeScale;
			originalFixedDeltaTime = Time.fixedDeltaTime;
		}
		else if (instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		delayInProgress = false;
		Object.DontDestroyOnLoad(gameObject);
	}

	public static void Pause(bool status)
	{
		paused = status;
		SoundManager.TogglePause(paused);
		if (paused)
		{
			timeScaleAtPause = CurrentTimeScale;
			CurrentTimeScale = 0f;
		}
		else
		{
			CurrentTimeScale = ((!delayInProgress) ? originalTimeScale : timeScaleAtPause);
		}
	}

	private static IEnumerator TimeScaleDelayOverRealTime(float realTime, float targetTimeScale, bool ignoreAllPreviousDelays)
	{
		if (ignoreAllPreviousDelays)
		{
			CurrentTimeScale = targetTimeScale;
			realTimeDelay = realTime;
			baseRealTimeDelay = realTimeDelay;
		}
		else
		{
			if (targetTimeScale < CurrentTimeScale)
			{
				CurrentTimeScale = targetTimeScale;
			}
			if (realTimeDelay < realTime)
			{
				realTimeDelay += realTime;
				baseRealTimeDelay = realTimeDelay;
			}
		}
		if (delayInProgress)
		{
			yield break;
		}
		delayInProgress = true;
		while (realTimeDelay > 0f && CurrentTimeScale < originalTimeScale)
		{
			if (!paused)
			{
				if (easeOut)
				{
					CurrentTimeScale = Mathf.Lerp(t: Mathf.Pow(realTimeDelay / baseRealTimeDelay, 0.5f), a: originalTimeScale, b: targetTimeScale);
				}
				realTimeDelay -= Time.unscaledDeltaTime;
			}
			yield return null;
		}
		delayInProgress = false;
		CurrentTimeScale = originalTimeScale;
	}

	public static void StopTimeScaleDelay()
	{
		realTimeDelay = 0f;
		CurrentTimeScale = originalTimeScale;
		delayInProgress = false;
	}

	public static void SetTimeScaleDelayOverRealTime(float realTime, float timeScale = 0.01f, bool useEaseOut = true, bool ignoreAllPrevDelays = false)
	{
		easeOut = useEaseOut;
		instance.StartCoroutine(TimeScaleDelayOverRealTime(realTime, timeScale, ignoreAllPrevDelays));
	}

	public static void StandardFreezeIntoEaseOutTimeScale()
	{
		StopTimeScaleDelay();
		instance.StartCoroutine(FreezeEaseOut());
	}

	public static void FreezeForFrames(int frames = 1, bool ignoreAllPrevious = false)
	{
		StopTimeScaleDelay();
		SetTimeScaleDelayOverRealTime(0.01666f * (float)frames, 0f, useEaseOut: false, ignoreAllPrevious);
	}

	private static IEnumerator FreezeEaseOut()
	{
		CameraController.ShakeCamera();
		SetTimeScaleDelayOverRealTime(0.35f, 0.01f, useEaseOut: false, ignoreAllPrevDelays: true);
		while (delayInProgress)
		{
			yield return null;
		}
		SetTimeScaleDelayOverRealTime(0.5f, 0.01f, useEaseOut: true, ignoreAllPrevDelays: true);
	}
