	private bool IsSkillOriginator(GameObject other)
	{
		return other != null && other.transform.parent != null && (other.transform.parent.gameObject == parentObject || other.transform.parent.gameObject.name.Contains(atkInfo.skillCategory));
	}

	private bool IsAllyCheck(string attackName, string targetName)
	{
		return !GameController.pvpOn && attackName.StartsWith("Player") && targetName.StartsWith("Ally");
	}

	public void ExecuteAttack(Collider2D col)
	{
		targetHealth = col.gameObject.GetComponent<Health>() ?? col.transform.parent.gameObject.GetComponent<Health>();
		if (targetHealth == null)
		{
			return;
		}
		onHitAtkInfo = new AttackInfo(atkInfo);
		onHitAtkInfo.time = Time.time;
		onHitAtkInfo.targetObjID = col.gameObject.GetInstanceID();
		onHitAtkInfo.attackerPosition = transform.position;
		onHitAtkInfo.targetPosition = col.transform.position;
		if (targetHealth.passThroughAttack)
		{
			targetHealth.TakeDamage(onHitAtkInfo, onHitAtkInfo.entity, critPreCalculated: true);
			return;
		}
		if (Random.value < targetHealth.evadeStat.CurrentValue)
		{
			EvadeAttack(onHitAtkInfo, col);
			return;
		}
		if (!damageModifierApplied && onHitAtkInfo.damage > 0)
		{
			damageModifierApplied = true;
			onHitAtkInfo.damage = Mathf.Max(1, Mathf.FloorToInt((float)onHitAtkInfo.damage * damageModifier));
		}
		if (damageOverride > -1)
		{
			onHitAtkInfo.damage = damageOverride;
		}
		if (damageOverride == 0)
		{
			onHitAtkInfo.canHitStun = false;
			onHitAtkInfo.showDamageEffect = false;
			onHitAtkInfo.showDamageNumber = false;
		}
		onHitAtkInfo.attackingVector = (col.transform.position - transform.position).normalized;
		onHitAtkInfo.knockbackVector = GetKnockbackVector(col.transform.position, transform.position, onHitAtkInfo.knockbackMultiplier, onHitAtkInfo.knockbackOverwrite, attackerPosOffet);
		if (onHitAtkInfo.shakeCamera)
		{
			CameraController.ShakeCamera(Mathf.Min((float)onHitAtkInfo.damage * CamShakeMultiplier.CurrentValue, 2f));
		}
		AnnounceCollisionEvent(col, targetHealth.entityScript);
		if (!targetHealth.invulnerable && Random.value < onHitAtkInfo.critHitChance)
		{
			if (targetHealth.evadeCrit)
			{
				EvadeAttack(onHitAtkInfo, col);
				return;
			}
			if (globalCritEventHandlers != null)
			{
				globalCritEventHandlers(onHitAtkInfo, onHitAtkInfo.entity, targetHealth.entityScript);
			}
			onHitAtkInfo.isCritical = true;
			onHitAtkInfo.damage = Mathf.FloorToInt(onHitAtkInfo.critDmgModifier * (float)onHitAtkInfo.damage);
		}
		if (onHitAtkInfo.isUltimate)
		{
			onHitAtkInfo.damage = Mathf.FloorToInt(onHitAtkInfo.odDmgModifier * (float)onHitAtkInfo.damage);
		}
		if (onHitAtkInfo.isDamageOverride)
		{
			onHitAtkInfo.damage = atkInfo.damage;
		}
		targetHealth.TakeDamage(onHitAtkInfo, onHitAtkInfo.entity, critPreCalculated: true);
		UpdateAttackHistory(onHitAtkInfo.attackInfoKey, onHitAtkInfo);
	}

	public void OnTriggerEnter2D(Collider2D col)
	{
		if (atkInfo != null && CheckCollision(col, col.gameObject.GetInstanceID()))
		{
			ExecuteAttack(col);
		}
	}

	public void UpdateAttackHistory(string givenKey, AttackInfo givenAtkInfo)
	{
		if (!attackHistory.ContainsKey(givenKey))
		{
			attackHistory[givenKey] = new FixedSizeQueue<AttackInfo>(15);
		}
		attackHistory[givenKey].Enqueue(givenAtkInfo);
	}

	public bool CheckAttackHistory(int targetObjID)
	{
		if (!attackHistory.ContainsKey(atkInfo.attackInfoKey))
		{
			return true;
		}
		sameTargetTimeVal = atkInfo.sameTargetImmunityTime;
		sameAttackTimeVal = atkInfo.sameAttackImmunityTime;
		atkHistQueue = attackHistory[atkInfo.attackInfoKey];
		if (sameTargetTimeVal > 0f)
		{
			if (sameAttackTimeVal > 0f)
			{
				for (int num = 14; num >= 0; num--)
				{
					atkHistInfo = atkHistQueue.GetAtIndex(num);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID)
					{
						timeDiff = Time.time - atkHistInfo.time;
						if (sameTargetTimeVal > timeDiff || (sameAttackTimeVal > timeDiff && atkHistInfo.atkObjID == AttackerObjID))
						{
							return false;
						}
					}
				}
			}
			else
			{
				for (int num2 = 14; num2 >= 0; num2--)
				{
					atkHistInfo = atkHistQueue.GetAtIndex(num2);
					if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameTargetTimeVal > Time.time - atkHistInfo.time)
					{
						return false;
					}
				}
			}
		}
		else if (sameAttackTimeVal > 0f)
		{
			for (int num3 = 14; num3 >= 0; num3--)
			{
				atkHistInfo = atkHistQueue.GetAtIndex(num3);
				if (atkHistInfo != null && atkHistInfo.targetObjID == targetObjID && sameAttackTimeVal > Time.time - atkHistInfo.time && atkHistInfo.atkObjID == AttackerObjID)
				{
					return false;
				}
			}
		}
		return true;
	}

	public AttackInfo GenerateAttackInfo(StatData curStatData, int skillLevel, bool isUltimate)
	{
		if (curStatData == null)
		{
			return null;
		}
		if (curStatData.category.Contains("Player"))
		{
			if (curStatData.category.EndsWith("0"))
			{
				generatedEntity = GameController.playerScripts[0];
			}
			else if (curStatData.category.EndsWith("1"))
			{
				generatedEntity = GameController.playerScripts[1];
			}
		}
		else
		{
			generatedEntity = entityScript;
		}
		generatedAtkInfo = AttackInfo.GetInfoFromData(generatedEntity, curStatData, skillLevel, isUltimate);
		generatedAtkInfo.knockbackOverwrite = !disableKnockbackOverwrite && generatedAtkInfo.knockbackOverwrite;
		generatedAtkInfo.attacker = attackerName;
		generatedAtkInfo.atkObjID = AttackerObjID;
		if (entityScript != null)
		{
			generatedAtkInfo.gameObject = entityScript.gameObject;
		}
		else if (transform.parent != null)
		{
			generatedAtkInfo.gameObject = transform.parent.gameObject;
		}
		else
		{
			generatedAtkInfo.gameObject = gameObject;
		}
		return generatedAtkInfo;
	}

	public void EvadeAttack(AttackInfo givenInfo, Collider2D givenCol)
	{
		OverheadNumberPool.DisplayOverheadNumber(TextManager.GetUIText("combat-evade"), givenCol.transform.position, (!givenInfo.skillCategory.Contains("Player")) ? Globals.evadeColor : Globals.evadeEnemyColor, OverheadNumber.defaultBorderColor, givenCol.transform.position, givenCol.transform, 0.5f);
		givenInfo.sameAttackImmunityTime = 0.5f;
		UpdateAttackHistory(givenInfo.attackInfoKey, givenInfo);
		if (targetHealth != null)
		{
			targetHealth.AnnounceEvadeEvent();
		}
		SoundManager.PlayWithDistAndSPR("ImpactEvade", transform.position);
	}

	public Vector2 GetKnockbackVector(Vector2 targetPos, Vector2 attackerPos, float kbMultiplier, bool kbOverwrite, Vector2 atkOffset = default(Vector2))
	{
		if (knockbackMultiplierOverride >= 0f)
		{
			kbMultiplier = knockbackMultiplierOverride;
		}
		if (kbMultiplier == 0f)
		{
			return Vector2.zero;
		}
		if (kbOverwrite)
		{
			return knockbackOverwriteVector.normalized * kbMultiplier;
		}
		calcKnockbackVector = targetPos - attackerPos + atkOffset;
		return calcKnockbackVector.normalized * kbMultiplier;
	}

	public bool CheckCollision(Collider2D col, int targetObjID)
	{
		if (atkInfo == null || col == null)
		{
			return false;
		}
		checkColObjNameStr = col.gameObject.name;
		if (IsAllyCheck(atkInfo.skillCategory, checkColObjNameStr) || IsSkillOriginator(col.gameObject) || ignoreTargetsList.Contains(targetObjID))
		{
			return false;
		}
		return isActiveAndEnabled && CheckAttackHistory(targetObjID) && atkInfo.targetNames.Contains(checkColObjNameStr);
	}

	public AttackInfo SetAttackInfo(string newSkillCat, string newSkillID, int newSkillLevel = 1, bool newIsUltimate = false)
	{
		statData = StatManager.GetSkillData(newSkillCat, newSkillID);
		atkInfo = GenerateAttackInfo(statData, newSkillLevel, newIsUltimate);
		return atkInfo;
	}

	public void SetAttackInfo(AttackInfo newAtkInfo, int givenLevel = -1)
	{
		statData = StatManager.GetSkillData(newAtkInfo.skillCategory, newAtkInfo.skillID);
		atkInfo = new AttackInfo(newAtkInfo);
		if (givenLevel > -1)
		{
			ChangeAttackInfoLevel(givenLevel);
		}
	}

	public AttackInfo ChangeAttackInfoLevel(int level)
	{
		return (atkInfo != null) ? SetAttackInfo(atkInfo.skillCategory, atkInfo.skillID, level, atkInfo.isUltimate) : null;
	}

	public AttackInfo GetAtkInfoAtLevel(int givenLevel)
	{
		return (statData != null && atkInfo != null) ? GenerateAttackInfo(statData, givenLevel, atkInfo.isUltimate) : null;
	}

	private void OnDestroy()
	{
		if (atkInfo != null)
		{
			Health.atkObjIDDict.Remove(atkInfo.atkObjID);
		}
	}

	public void EnableForOneFrame(bool destroyOnDisable = false, bool enableComponent = false)
	{
		StartCoroutine(HandleEnableForOneFrame(destroyOnDisable, enableComponent));
	}

	private IEnumerator HandleEnableForOneFrame(bool destroyOnDisable = false, bool enableComponent = false)
	{
		if (enableComponent)
		{
			enabled = true;
		}
		collider.enabled = true;
		yield return new WaitForFixedUpdate();
		if (Time.inFixedTimeStep)
		{
			yield return new WaitForFixedUpdate();
		}
		collider.enabled = false;
		if (destroyOnDisable)
		{
			Object.Destroy(gameObject);
		}
	}
}

