private IEnumerator SetInvulnerable(float duration, bool showMsg)
{
	if (invulnerableCoroutineActive)
	{
		ChaosStopwatch.Refresh(invulnerabilityStopwatchID, duration);
		yield break;
	}
	invulnerableCoroutineActive = true;
	bool originalInvulStatus = invulnerable;
	bool originalInvulMsgStatus = showInvulnerableMsg;
	invulnerable = true;
	showInvulnerableMsg = showMsg;
	invulnerabilityStopwatchID = ChaosStopwatch.Begin(duration);
	while (!ChaosStopwatch.Check(invulnerabilityStopwatchID))
	{
		yield return null;
	}
	invulnerable = originalInvulStatus;
	showInvulnerableMsg = originalInvulMsgStatus;
	invulnerableCoroutineActive = false;
}
public IEnumerator FlashRed()
{
	if (entitySprites.Count == 0)
	{
		yield break;
	}
	for (int i = 0; i < entitySprites.Count; i++)
	{
		if (!(entitySprites[i] == null))
		{
			if (entitySprites[i].name.Contains("Player"))
			{
				entitySprites[i].material.SetVector("_FlashColor", new Vector4(0.6f, 0.1f, 0.1f, 1f));
			}
			entitySprites[i].material.SetFloat("_FlashAmount", 1f);
		}
	}
	yield return waitForFlashDelay;
	for (int j = 0; j < entitySprites.Count; j++)
	{
		if (!(entitySprites[j] == null))
		{
			entitySprites[j].material.SetFloat("_FlashAmount", 0f);
		}
	}
	entitySprites = entitySprites.Where((SpriteRenderer y) => y != null).ToList();
}

