public void ResetPlayer(bool originPosition = true, bool fullyRestoreHealth = false, bool resetState = true, bool resetOverdrive = true, float restoreHealthPercentage = 0f)
{
	Show();
	deathMenu.SetActive(value: false);
	if (resetState)
	{
		fsm.ChangeState(fsm.defaultStateName);
	}
	if (originPosition)
	{
		transform.position = myOrigin;
		lastCheckpoint = myOrigin;
	}
	movement.EndMovement();
	if (fullyRestoreHealth)
	{
		health.healthStat.CurrentValue = health.healthStat.ModifiedValue;
	}
	else
	{
		restoreHealthPercentage = Mathf.Clamp01(restoreHealthPercentage);
		if (restoreHealthPercentage > 0f)
		{
			health.healthStat.CurrentValue = Mathf.CeilToInt(health.healthStat.ModifiedValue * restoreHealthPercentage);
		}
	}
	if (resetOverdrive)
	{
		OverdriveProgress = 0f;
		ToggleOverdriveEffects(status: false);
	}
	hurtBoxObj.SetActive(value: true);
	if (overheadPrompt != null)
	{
		overheadPrompt.HidePrompt(string.Empty);
	}
	cooldownManager.ResetCooldowns();
	RegisterPlayer();
	floorContact.SetActive(value: true);
