using UnityEngine;
public class SlowDotEffect : DoTEffect
{
	private static GameObject prefab;
	public static string slowStatusStr = "SlowStatus";
	[HideInInspector]
	public BaseEffect effectObject;
	public string modIDString = "SlowDot";
	public float slowValue = 0.5f;
	private bool effectIsActive;
	private bool effectAllowed;
	private bool slowApplied;
	[HideInInspector]
	public NumVarStatMod slowMod;
	private string parentStateName;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/SlowEffect.prefab"));
	public SlowDotEffect(string newCat, int newLvl, Entity newEnt, Entity atkEnt)
		: base(newCat, slowStatusStr, newLvl, newEnt, atkEnt)
	{
		useInterval = false;
		SetSlowValues(newLvl);
		damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
		dotElement = ElementType.Air;
	}
	public override bool Update()
	{
		if (parentEntity == null || parentEntity.health == null || parentEntity.health.healthStat.CurrentValue <= 0f || ChaosStopwatch.Check(damageStopwatchID))
		{
			CleanUp();
			ToggleMovementMods(status: false);
			if (effectObject != null)
			{
				effectObject.Disable();
			}
			return true;
		}
		parentStateName = parentEntity.currentStateName;
		effectAllowed = parentStateName.Contains("Run") || parentStateName.Contains("Chase") || parentStateName.Contains("GoBack") || parentStateName.Contains("Surround");
		if (effectIsActive && !effectAllowed)
		{
			CleanUp();
		}
		if (!effectIsActive && effectAllowed)
		{
			Init();
		}
		return false;
	}
	public override void Refresh(int hits = 0, float time = 0f)
	{
		base.Refresh(hits, time);
		PlayAudio();
		ToggleMovementMods(status: true);
	}
	public override void Init()
	{
		if (!(parentEntity == null))
		{
			if (effectObject == null)
			{
				CreateEffectObject();
			}
			if (!slowApplied)
			{
				slowApplied = true;
				ToggleMovementMods(status: true);
			}
			effectIsActive = true;
			if (parentEntity.animSpeedHandler != null)
			{
				parentEntity.animSpeedHandler.Modify(slowMod, givenStatus: true);
			}
		}
	}
	public override void InitDotVars()
	{
		SetSlowValues(skillLevel);
	}
	public override void CleanUp()
	{
		effectIsActive = false;
		if (parentEntity != null && parentEntity.animSpeedHandler != null)
		{
			parentEntity.animSpeedHandler.Modify(slowMod, givenStatus: false);
		}
	}
	public virtual void SetSlowValues(int givenLevel)
	{
		skillLevel = Mathf.Max(1, givenLevel);
		switch (skillLevel)
		{
		case 1:
			damageInterval = 1.75f;
			slowValue = 0.375f;
			break;
		case 2:
			damageInterval = 2f;
			slowValue = 0.5f;
			break;
		case 3:
			damageInterval = 2.25f;
			slowValue = 0.625f;
			break;
		case 4:
			damageInterval = 2.5f;
			slowValue = 0.6875f;
			break;
		default:
			damageInterval = 2.75f;
			slowValue = 0.75f;
			break;
		}
		slowMod = new NumVarStatMod(modIDString, 0f - slowValue, 7, VarStatModType.Multiplicative);
	}
	public virtual void ToggleMovementMods(bool status)
	{
		if (!(parentEntity == null) && !(parentEntity.movement == null))
		{
			parentEntity.movement.moveSpeedStat.Modify(slowMod, status);
			parentEntity.movement.dashSpeedStat.Modify(slowMod, status);
		}
	}
	public virtual void CreateEffectObject()
	{
		effectObject = Globals.ChaosInst<BaseEffect>(Prefab, parentEntity.transform.parent, parentEntity.hurtBoxTransform.position);
		effectObject.entity = parentEntity;
		PlayAudio();
	}
	public virtual void PlayAudio()
	{
		SoundManager.PlayAudioWithDistance("SlowEffect", parentEntity.transform.position);
	}
}
using UnityEngine;
public class RootDotEffect : DoTEffect
{
	private GameObject rootEffectPrefab;
	private BaseEffect effectObject;
	private Animator effectAnim;
	private const string rootModID = "RootDot";
	private bool rootApplied;
	private static NumVarStatMod rootNumMod;
	private static BoolVarStatMod rootBoolMod;
	public RootDotEffect(string skillCat, string skillID, int newSkillLevel, Entity parentEntity, Entity attackEntity, bool instant = true, float duration = 2f)
		: base(skillCat, skillID, newSkillLevel, parentEntity, attackEntity, instant)
	{
		useInterval = false;
		damageInterval = duration * ((!GameController.pvpOn || !(parentEntity is Player)) ? 1f : 0.4f);
		damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
		rootEffectPrefab = ChaosBundle.Get("Assets/Prefabs/Effects/RootEffect.prefab");
	}
	public override bool Update()
	{
		if (parentEntity == null || parentEntity.health == null || parentEntity.health.healthStat.CurrentValue <= 0f || ChaosStopwatch.Check(damageStopwatchID))
		{
			ToggleMovementMods(parentEntity, status: false);
			if (effectObject != null)
			{
				effectAnim.Play("Destroy", -1, 0f);
			}
			return true;
		}
		return false;
	}
	public override void Init()
	{
		if (!(parentEntity == null))
		{
			if (effectObject == null)
			{
				effectObject = Object.Instantiate(rootEffectPrefab, parentEntity.hurtBoxTransform.position, Quaternion.identity).GetComponent<BaseEffect>();
				effectObject.entity = parentEntity;
				effectAnim = effectObject.GetComponent<Animator>();
			}
			if (!rootApplied)
			{
				rootApplied = true;
				ToggleMovementMods(parentEntity, status: true);
			}
		}
	}
	public static void ToggleMovementMods(Entity givenEntity, bool status, bool setMovement = true, bool setKnockback = true, string modID = "RootDot")
	{
		if (!(givenEntity == null))
		{
			rootNumMod = GetRootNumMod(modID);
			rootBoolMod = GetRootBoolMod(modID);
			if (setMovement && givenEntity.movement != null)
			{
				givenEntity.movement.moveSpeedStat.Modify(rootNumMod, status);
				givenEntity.movement.dashSpeedStat.Modify(rootNumMod, status);
			}
			if (setKnockback && givenEntity.health != null)
			{
				givenEntity.health.ignoreKnockbackVarStat.Modify(rootBoolMod, status);
			}
		}
	}
	private static NumVarStatMod GetRootNumMod(string modID = "RootDot")
	{
		return new NumVarStatMod(modID, 0f, 7, VarStatModType.Override);
	}
	private static BoolVarStatMod GetRootBoolMod(string modID = "RootDot")
	{
		return new BoolVarStatMod(modID, Health.skillIgnoreMod);
	}
}

